/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// This class posts free text invoices for the AMEX customers as per their AMEX charges.
/// </summary>
class METAMEXCustFreeTextInvService extends SysOperationServiceBase
{
    LedgerJournalTable                      ledgerJournalTable;
    DimensionAttributeValuecombination      dimensionAttribute;
    CustInvoiceTable                        custInvoiceTable;
    CustInvoiceLine                         custInvoiceLine;
    METCustTable                            metCustTable ;    
    LineNum                                 lineNum;

    LedgerDimensionAccount                  lineLedgerDimension;

    CustParameters                          parameters;

}

Method.Source:
    /// <summary>
    /// Executes the business logic
    /// </summary>
    /// <param name = "_contract"><c>METAMEXCustFreeTextInvContract</c> class instance</param>
    private void runOperation(METAMEXCustFreeTextInvContract    _contract)
    {
        LedgerJournalTrans                  ledgerJournalTrans;
        int                                 bundlesize, totalRecords, totalTasks, i, j, task;
        List                                companyCustList      = new List(Types::Container);
        date                                cutoffDate = mkDate(18,12,2021);
        date                                journalPostedDate;
        METAMEXProcessFTI                   adhocFTI = _contract.parmProcessAdhocFTI();
        JournalId                           journalNumber;
        LedgerJournalTable                  journalTable;

        if(!_contract.parmJournalId() && !adhocFTI)
        {
            _contract.parmJournalId(CustParameters::find().METAMEXFreeTextInvJournal);
        }

        journalNumber = _contract.parmJournalId();

        BatchHeader batchHeader = this.getCurrentBatchHeader();

        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }

        if (adhocFTI)
        {
            batchHeader.parmCaption("@MET:BatchJobAdhocFTI");
        }
        else
        {
            batchHeader.parmCaption("@MET:AMEXFreeTextInvServiceBatchDesc");
        }
    
        while select journalTable
            where (journalNumber && journalTable.JournalNum == journalNumber) ||
            (adhocFTI && journalTable.METAMEXProcessFTI)
        {
            journalPostedDate   = DateTimeUtil::date(journalTable.PostedDateTime);

            if (!journalTable ||
            !journalTable.Posted ||
            journalPostedDate < cutoffDate ||
            journalTable.JournalName != CustParameters::find().METAMEXJournalName)
            {
                warning(strFmt("@MET:METAMEXJournalNotPostedError", journalTable.JournalNum));
                continue;
            }

            totalTasks      =   _contract.parmTasks();
            if (totalTasks <= 0)
            {
                totalTasks = 1;
            }
            task = 1;
            j = 0;
            i = 0;
            totalrecords = 0;

            while select count (RecId) from ledgerJournalTrans
            group by Company, LedgerDimension
            where ledgerJournalTrans.JournalNum == journalTable.JournalNum
            {
                totalrecords++;
            }

            bundleSize      =   real2int(roundUp((totalrecords / totalTasks), 1.0));

            while select crosscompany Company, LedgerDimension from ledgerJournalTrans
            group by Company, LedgerDimension
            where ledgerJournalTrans.JournalNum == journalTable.JournalNum &&
            ledgerJournalTrans.DataAreaId == journalTable.DataAreaId &&
            !ledgerJournalTrans.AmountCurDebit

            join DisplayValue from dimensionAttribute group by DisplayValue
                where dimensionAttribute.RecId == ledgerJournalTrans.LedgerDimension

            {
                select  crosscompany RecId from custInvoiceTable
                where custInvoiceTable.METAMEXJournalId == journalTable.JournalNum &&
                custInvoiceTable.DataAreaId == ledgerJournalTrans.Company &&
                custInvoiceTable.OrderAccount == dimensionAttribute.DisplayValue;

                if (custInvoiceTable)
                {
                    continue;
                }

                i++;
                j++;
                companyCustList.addEnd([ledgerJournalTrans.Company, dimensionAttribute.DisplayValue]);
                if (i  == bundleSize || j == totalRecords)
                {
                    SysOperationServiceController createInvController = new SysOperationServiceController(
                                                                classStr(METAMEXCustFreeTextInvService),
                                                                methodStr(METAMEXCustFreeTextInvService, postInvoiceSubTask));
                    createInvController.parmDialogCaption(strFmt("@MET:METAMEXPostFreeTextInvoicesSubTask", task, journalTable.JournalNum));

                    METAMEXCustFreeTextInvContract invContract = createInvController.getDataContractObject() as METAMEXCustFreeTextInvContract;
                    invContract.parmJournalId(journalTable.JournalNum);
                    invContract.parmcompanyCustList(companyCustList);
                    invContract.parmDataArea(_contract.parmDataArea());

                    batchHeader.addRuntimeTask(createInvController, this.getCurrentBatchTask().RecId);
                    companyCustList = new List(Types::Container);
                    task++;
                    i = 0;
                }

            }

            //unflag journal for Adhoc job
            if (adhocFTI)
            {
                ttsbegin;
                journalTable.selectForUpdate(true);
                journalTable.METAMEXProcessFTI = NoYes::No;
                journalTable.doUpdate();
                ttscommit;
            }
        }
        batchHeader.save();
    }

    /// <summary>
    /// Performs the actual operation to create and post invoices per company and per customer.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXCustFreeTextInvContract</c> class instance.</param>
    private void postInvoiceSubTask(METAMEXCustFreeTextInvContract    _contract)
    {
        #OCCRetryCount

        LedgerJournalTrans      ledgerJournalTrans;
        ListEnumerator          companyCustListEnum;
        METAmexCharge           chargeAmount;
        boolean                 hasError;
        container               companyCustCon;
        str                     company;
        str                     customer;

        parameters              = CustParameters::findByCompany(_contract.parmDataArea());
        companyCustListEnum      = _contract.parmcompanyCustList().getEnumerator();
        ledgerJournalTable      = LedgerJournalTable::find(_contract.parmJournalId());

        while (companyCustListEnum.moveNext())
        {
            try
            {
                ttsBegin;
                companyCustCon = companyCustListEnum.current();
                company = conPeek(companyCustCon, 1);
                customer = conPeek(companyCustCon, 2);
                lineNum  = 0;           
                while select LedgerDimension, Company, AmountCurDebit, AmountCurCredit, TransDate from ledgerJournalTrans
                    where ledgerJournalTrans.JournalNum == ledgerJournalTable.JournalNum
                    && ledgerJournalTrans.company == company
                    && ledgerJournalTrans.PaymentStatus != CustVendPaymStatus::Rejected
                    && !ledgerJournalTrans.AmountCurDebit
                    join dimensionAttribute
                    where dimensionAttribute.RecId == ledgerJournalTrans.LedgerDimension
                    && dimensionAttribute.DisplayValue == customer
                {
                    custInvoiceTable.clear();

                    //To create invoice in specific company
                    changecompany(ledgerJournalTrans.company)
                    {
                        custInvoiceTable = null;
                        CustInvoiceLine  = null; 
                        metCustTable     = null; 
                        metCustTable = METCustTable::find(dimensionAttribute.DisplayValue);
                        if (metCustTable.AMEXChargeAccount)
                        {
                            metCustTable = metCustTable.getAMEXChargeAccount();
                        }
                        chargeAmount = metCustTable.AMEXChargeFee;
                        if (chargeAmount)
                        {
                            select * from custInvoiceTable
                            where custInvoiceTable.METAMEXJournalId == _contract.parmJournalId()
                            && custInvoiceTable.OrderAccount == metCustTable.AccountNum
                            && custInvoiceTable.DataAreaId == company
                            && !custInvoiceTable.Posted;

                            if (!custInvoiceTable)
                            {
                                custInvoiceTable = this.createInvoiceHeader(
                                                    CustTable::find(metCustTable.AccountNum),
                                                    _contract.parmJournalId());
                            }
                        }
                        else
                        {
                            error(strFmt("@MET:METAMEXChargeNotFoundError", dimensionAttribute.DisplayValue, company));
                            hasError = true;
                        }

                        if(custInvoiceTable)
                        {
                            lineNum++;
                            this.createInvoiceLine(ledgerJournalTrans , custInvoiceTable, chargeAmount);
                        }
                    }
                }
                //To post invoice in specific company
                changecompany(custInvoiceTable.DataAreaId)
                {
                    //MPJ-16899
                    Amount      ftiInvoiceAmount = custInvoiceTable.displayInvoiceAmount();
                    if (ftiInvoiceAmount < 2)
                    {
                        custInvoiceTable.selectForUpdate(true);
                        custInvoiceTable.delete();
                    }

                    custInvoiceTable.reread();
                    if (custInvoiceTable)
                    {
                        METAMEXCustPostInvoice custPostInvoice = METAMEXCustPostInvoice::construct(custInvoiceTable,
                                                                CustParameters::find().CreditMaxCheck,
                                                                NoYes::No);
                        custPostInvoice.run();
                    }
                }
                ttsCommit;
            }
            catch (Exception::Error)
            {
                error (strFmt("@MET:METAMEXFreeTxtInvError", customer, company));
                hasError = true;
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error (strFmt("@MET:METAMEXFreeTxtInvError", customer, company));
                    error("@Subledger:DeadlockErrorThrown");
                    hasError = true;
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        error (strFmt("@MET:METAMEXFreeTxtInvError", customer, company));
                        error("@Subledger:UpdateConflictErrorThrown");
                        hasError = true;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    error (strFmt("@MET:METAMEXFreeTxtInvError", customer, company));
                    error("@Subledger:UpdateConflictErrorThrown");
                    hasError = true;
                }
            }
        }

        if (hasError)
        {
            throw Exception::Error;
        }

    }

    /// <summary>
    /// Creates <c>CustInvocieTable</c> record.
    /// </summary>
    /// <param name = "_custTable"><c>CustTable</c> buffer.</param>
    /// <param name = "_metAMEXJournalId">AMEX journal id.</param>
    /// <returns><c>CustInvoiceTable</c> record.</returns>
    private CustInvoiceTable createInvoiceHeader(CustTable _custTable,
                                                JournalId  _metAMEXJournalId)
    {
        custInvoiceTable = this.initializeCustInvoiceTable(_custTable);
        custInvoiceTable.InclTax = NoYes::No;
        custInvoiceTable.METAMEXJournalId = _metAMEXJournalId;
        custInvoiceTable.setListCode();
        custInvoiceTable.PaymMode = parameters.METAMEXChargePaymMode;
        custInvoiceTable.insert();

        return custInvoiceTable;
    }

    /// <summary>
    /// Initializes <c>CustInvoiceTable</c> buffer..
    /// </summary>
    /// <param name="_custTable">
    /// The <c>CustTable</c> record to use for initializing <c>CustInvoiceTable</c> fields.
    /// </param>
    /// <returns>
    /// The <c>CustInvoiceTable</c> instance.
    /// </returns>
    protected CustInvoiceTable initializeCustInvoiceTable(CustTable _custTable)
    {
        custInvoiceTable.initFromCustTable(_custTable);
        custInvoiceTable.InvoiceDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        custInvoiceTable.WorkflowApprovalStatus = CustFreeInvoiceWFApprovalStatus::Approved;
        custInvoiceTable.WorkflowApprovalState = CustFreeInvoiceWFApprovalState::Completed;

        return custInvoiceTable;
    }

    /// <summary>
    /// Creates the  invoice line.
    /// </summary>
    /// <param name = "_journalTrans">
    ///  <c>LedgerJournaTrans</c> buffer.
    ///  <c>LedgerJournaTrans</c> buffer.
    /// </param>
    /// <param name = "_invoice">
    /// An instance of <c>CustInvoiceTable</c> buffer.
    /// </param>
    /// <param name = "_amexFee">
    /// Amex charge amount.
    /// </param>
    /// <returns>
    /// returns the created customer invoice line <c>createInvoiceLine</c>.
    /// </returns>
    protected CustInvoiceLine createInvoiceLine(LedgerJournalTrans      _journalTrans,
                                                CustInvoiceTable        _invoice,
                                                METAMEXCharge           _amexFee)
    {
        CustInvoiceLine     newLine;
        AmountCur           amount = abs(_journalTrans.AmountCurDebit - _journalTrans.AmountCurCredit);

        newLine.initFromCustInvoiceTable(_invoice);

        newLine.LineNum = lineNum;
        newLine.ParentRecId     = _invoice.RecId;
        newLine.AmountCur       = (amount * _amexFee/100);
        newLine.Quantity        = 1;
        newLine.UnitPrice       = newLine.AmountCur;

        newLine.Description     = strFmt("@MET:METAMEXInvoiceDescription", _amexFee, amount, _journalTrans.TransDate);
        newLine.InvoiceTxt      = newLine.Description;
        newLine.TaxItemGroup    = parameters.METAMEXTaxItemGroup;
        newLine.TaxGroup        = parameters.METAMEXTaxGroup;
        
        newLine.LedgerDimension = parameters.METAMEXChargePostingLedgerDim;
        newLine.DefaultDimension = _invoice.mergeDimension(_journalTrans.DefaultDimension, _invoice.DefaultDimension);
        newLine.insert();

        return newLine;
    }
